const candidateSkin = process.env.MX_TEST_SKIN || 'style2';
const out = process.env.MX_OUTPUT_DIR || 'docs/styles/'+candidateSkin+'/implementation/round1';
const {chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');
const BASE=process.env.MX_AUDIT_URL||'http://127.0.0.1:5183';const CHROME=process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
(async()=>{const browser=await chromium.launch({executablePath:CHROME,headless:true});let page=await browser.newPage();await page.goto(BASE+'/tests/fixtures/layout-audit.html');await page.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});const scenes=await page.locator('select[aria-label=scene] option').evaluateAll(es=>es.map(e=>e.value));await page.close();const results=[];let index=0;
await Promise.all([0,1,2].map(async()=>{const p=await browser.newPage({viewport:{width:1100,height:1200}});const errors=[];p.on('pageerror',e=>errors.push(String(e)));while(index<scenes.length){const scene=scenes[index++];const pair=[];for(const skin of ['style1',candidateSkin]){try{await p.goto(BASE+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({scene,skin,layout:'balanced',width:440,height:782}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:45000});pair.push(await p.evaluate(()=>{const root=document.querySelector('#audit-stage');const visible=e=>!!e&&e.checkVisibility({visibilityProperty:true,opacityProperty:true})&&!e.closest('[hidden],[aria-hidden=true]');return {phase:root.dataset.phase,seats:root.querySelectorAll('.mx-seat').length,boards:[...root.querySelectorAll('.mx-board')].map(e=>e.querySelectorAll('.mx-public-slot').length),navigation:[...root.querySelectorAll('.mx-nav-button')].filter(visible).map(e=>e.dataset.action),actions:[...root.querySelectorAll('.mx-operation-row button')].filter(visible).map(e=>e.className),quick:[...root.querySelectorAll('.mx-quick-bet')].filter(visible).length,dialogs:[...root.querySelectorAll('[role=dialog]')].filter(visible).map(e=>e.className)}}));}catch(e){pair.push({error:String(e)})}}
const differences=Object.keys(pair[0]||{}).filter(k=>JSON.stringify(pair[0][k])!==JSON.stringify(pair[1]?.[k]));results.push({scene,pair,differences,errors:errors.splice(0)});if(results.length%20===0)console.log('Compared',results.length,'/',scenes.length)}await p.close()}));await browser.close();if(results.some(r=>r.differences.length||r.errors.length||r.pair.some(p=>p.error)))process.exitCode=1;fs.mkdirSync(out,{recursive:true});fs.writeFileSync(out+'/parity.json',JSON.stringify(results,null,2));console.log(JSON.stringify({scenes:results.length,failures:results.filter(r=>r.differences.length||r.errors.length||r.pair.some(p=>p.error))},null,2));})();
